import{_ as i,l as p,o as a,c as o,v as r,p as l,x as t,d as n,i as c,S as d}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"perf 采样","description":"","frontmatter":{"title":"perf 采样","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/perf-sampling.md","filePath":"cs/perf-sampling.md","lastUpdated":1789023840000}'),f={name:"cs/perf-sampling.md"};function h(_,e,m,P,u,A){const s=p("Mermaid");return a(),o("div",null,[e[1]||(e[1]=r('<h1 id="perf-采样" tabindex="-1">perf 采样 <a class="header-anchor" href="#perf-采样" aria-label="Permalink to &quot;perf 采样&quot;">​</a></h1><div class="epigraph"><p>perf 用 PMU 周期或事件溢出中断采样 IP，再靠 DWARF/帧指针归因到函数；也可记录 tracepoint 与 probe。</p><footer>—— 据 Linux perf_events 文档；Intel/ARM PMU；[cyclictest](/cs/latency-measurement) 为延迟对照</footer></div><p><a href="/cs/kprobes-uprobes">kprobe</a> 是点。<a href="/cs/printk-logging">printk</a> 是线。缺口是 <strong>统计采样</strong>：perf_events ABI、ring mmap、与开销。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>perf record -F</code>：每 N 个 cycle 采一个栈。缺口：skid；off-CPU 要用 sched 事件；内核与用户栈、<a href="/cs/kpti-os">KPTI</a> 下的解析。本课不把全部 PMU 事件当词典。</p><p><span class="marginnote">perf_event_open 是系统调用。cgroup 可限制谁能用 PMU。对象是性能计数，不是公平 Jain。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编程 PMU → 溢出 IRQ → 拷栈到 mmap 环 → 用户解析符号。对照 <a href="/cs/napi">NAPI</a>：都是中断采样思想。对照 <a href="/cs/blkio-cgroup">blkio</a>：I/O 统计另一条。对照 ASan：一个正确性，一个速度。</p>',8)),(a(),l(d,null,{default:t(()=>[c(s,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PMU%5B%22%E7%A1%AC%E4%BB%B6%E8%AE%A1%E6%95%B0%E6%BA%A2%E5%87%BA%22%5D%20--%3E%20SAMP%5B%22%E9%87%87%20IP%2F%E6%A0%88%22%5D%0A%20%20SAMP%20--%3E%20RING%5B%22mmap%20%E7%8E%AF%22%5D%0A%20%20RING%20--%3E%20SYM%5B%22%E7%94%A8%E6%88%B7%E7%AC%A6%E5%8F%B7%E5%8C%96%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>采样把「CPU 时间花在哪」变成直方图，是优化的默认入口。它改变被测物（probe effect）。不要写成火焰图产品教程（那是展示）。与 <a href="/cs/eas-scheduling">EAS</a>：freq 变则 cycle 含义变。</p><p>无帧指针且无 DWARF 则栈烂。</p><p>实现上：PEBS 减 skid 但仍不是指令精确。off-CPU 分析要 sched:sched_switch。无帧指针时要 DWARF 展开，内核与用户都要对应 debuginfo。 读法上只引用<a href="/cs/kprobes-uprobes">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>perf 采样</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 PEBS 细节。不保证虚拟化 PMU 真实。下一课可编程观测：eBPF。</p><p>版本字段会变，课序钉的是机制对象「perf 采样」，不是某一主线内核的结构体名。 后课默认：PMU 采样可归因热点。eBPF 观测程序，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>perf 用 PMU 或软件事件采样栈。</li><li>开销与 skid 要心里有数。</li><li>eBPF 观测是下一课。</li><li>出处：perf_events；内核 perf 文档。</li></ul>',11))])}const k=i(f,[["render",h]]);export{b as __pageData,k as default};
